// The commands of the runtime and the functions of the user libraries, as the compiler knows them (blitzcc --dump-keywords).
#pragma once
#include <map>
#include <string>
#include <vector>
#include "keywords.hpp"

namespace blitz::lsp {
	struct command_parameter {
		std::string name;
		std::string type;     // The name of the type: Int32, Float32, String, UInt64, Pointer, ...
		std::string fallback; // Default value as written, empty if the parameter is required
		bool        optional = false;
		bool        out      = false; // The command writes to the parameter
	};

	struct command {
		std::string                    name;    // As written in the manuals
		std::string                    lib;     // The library of a function of a user library, empty for the runtime
		std::string                    returns; // Empty if nothing
		std::vector<command_parameter> parameters;

		/** `Name(width:Int32, height:Int32, flags:Int32 = 0):Int32` */
		std::string signature() const;
	};

	class command_table {
		std::map<std::string, command> _by_name; // Lower case name
		public:
		/** Adds the functions; a name that is there already is replaced. Returns how many commands there are. */
		size_t add(std::vector<keywords::signature> const& functions);
		command const* find(std::string const& lower_name) const;
		std::map<std::string, command> const& all() const { return _by_name; }
	};
} // namespace blitz::lsp
